\coordinate (B) at (0,2.8);
\coordinate (A) at (0,0);
\coordinate (C) at (4.4,0.8);
\coordinate (E) at ($(B)!0.65!(C)$);
\coordinate (F) at ($(A)!0.65!(C)$);
\draw[thick] (B) -- (C) -- (A) -- cycle;
\draw[thick, blue!75!black] (E) -- (F);
\fill (A) circle (1.5pt) node[below left] {$A$};
\fill (B) circle (1.5pt) node[above left] {$B$};
\fill (C) circle (1.5pt) node[right] {$C$};
